#!/usr/bin/env node
'use strict';

// Only selected, explicitly CC0 source assets. Runtime files are generated by
// Blender; these immutable masters are never served by the game server.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const zlib = require('zlib');
const ROOT = path.resolve(__dirname, '..');
const OUTPUT = path.join(ROOT, 'source-assets/items/free-catalog-v1');
const CACHE = path.join(ROOT, 'Build/SourceDownloads/free-items-20260909');
const digest = bytes => crypto.createHash('sha256').update(bytes).digest('hex').toUpperCase();

const PACKS = [
  {
    id: 'space', file: 'kenney_space-kit.zip', creator: 'Kenney',
    page: 'https://kenney.nl/assets/space-kit',
    url: 'https://kenney.nl/media/pages/assets/space-kit/20874c75ac-1677698978/kenney_space-kit.zip',
    sha256: 'D5D7CDF2635ED5A43A9187DEAF409B6F47484E402321128341D3C3698E9EF4D9',
    folder: 'Models/GLTF format/',
    models: ['bones', 'meteor', 'meteor_half', 'meteor_detailed', 'rock',
      'rock_crystals', 'rock_crystalsLargeA', 'rock_crystalsLargeB',
      'pipe_ringHigh', 'pipe_cross', 'machine_generator', 'machine_wireless']
  },
  {
    id: 'station', file: 'kenney_space-station-kit.zip', creator: 'Kenney',
    page: 'https://kenney.nl/assets/space-station-kit',
    url: 'https://kenney.nl/media/pages/assets/space-station-kit/6475288f2e-1712749919/kenney_space-station-kit.zip',
    sha256: '215E79BD5415CFF93665183390F0343ED9ACF87780306331013B78520170C6D8',
    folder: 'Models/GLB format/',
    models: ['container-flat', 'container-tall', 'container', 'computer-screen', 'wall-switch', 'pipe-ring']
  },
  {
    id: 'survival', file: 'kenney_survival-kit.zip', creator: 'Kenney',
    page: 'https://kenney.nl/assets/survival-kit',
    url: 'https://kenney.nl/media/pages/assets/survival-kit/4065a8185b-1712149243/kenney_survival-kit.zip',
    sha256: 'C3586341B5932C87EB43D75D915434F47DAED168B17ED36A03E8CA9977C7443E',
    folder: 'Models/GLB format/', models: ['bedroll-packed', 'bottle', 'metal-panel-screws-half']
  }
];
const DIRECT = [
  ['heart', 'Heart', 'Quaternius', '1yCRUwFnwX', 'a53d4e74-46dd-43d3-9815-82cef1fa8ccc', 'A4ACAC986A8D557AA1BD9FFAD4291EC26C7E49F6FAAA716943C22394F42F5793'],
  ['spring', 'Spring', 'Quaternius', 'vKySckBbyb', 'c8301112-1eee-45cb-aa31-f8b161f6f25c', '5AC89D36B8D748E6B2FE6974D4D8CC19B04682835B38C8B6DD90496E367184E5'],
  ['medkit', 'Pickup Health', 'Quaternius', 'ijqVDSeIM5', '5b1bed20-e3b8-4687-b50a-43085ff69500', '9C8436DA2DE11C937BE7FB5541DE1CE81FEA45FA5B0D3A769104799D28CCBAF0'],
  ['gem-green', 'Gem Green', 'Quaternius', 'kbgiCMzdxg', '975e55e6-5400-4fd1-97a1-6deaebb19c1a', '6A29E5681BD6525AF84F1016E3E32B18C9008EFBA128DE8131232911504B1515'],
  ['gem-pink', 'Gem Pink', 'Quaternius', 'PJnKvWluqs', '97fcdb07-9d4d-46f2-8c17-392bb61915e6', 'AD216953C74193455A56F0EA40F36B1ED7BD714F21459A59ED74FA0E34EFE312'],
  ['backpack', 'Backpack', 'Quaternius', 'vF7TuXCPDH', '2eb5178b-0c98-4a0d-b0ea-ad8925525d1e', '404AF15A4BC0A955D9D8133D16DE7A4B900663F3A11F5364624AB8E7E9B6F68A'],
  ['radio', 'Radio', 'Kenney', 'ShNRjTDU3i', '33bdb52a-7a35-40f5-92db-870db8b1955e', '2DF48F5B08A00608E6E98A3AD18E1F0049E09BA6C1AF0549DA82E6F347694629']
].map(([id, title, creator, pageId, fileId, sha256]) => ({
  id, title, creator, sha256, file: id + '.glb', page: 'https://poly.pizza/m/' + pageId,
  url: 'https://static.poly.pizza/' + fileId + '.glb'
}));
DIRECT.push({ id: 'anchor', title: 'Prop Anchor', creator: 'Quaternius', file: 'anchor.gltf',
  page: 'https://quaternius.com/packs/piratekit.html',
  url: 'https://raw.githubusercontent.com/agentkaerf/FreeModels/db3df04d1e4714298a09510b26fb6de6645138a2/Pirate%20Kit%20-%20Nov%202023/glTF/Prop_Anchor.gltf',
  sha256: '98504894D03160B86F8B4A34D6E1B9B31BAC173CE424378100F13143FD0223FC' });

async function download(source) {
  const file = path.join(CACHE, source.file);
  let bytes = fs.existsSync(file) ? fs.readFileSync(file) : null;
  if (!bytes || digest(bytes) !== source.sha256) {
    const response = await fetch(source.url, { signal: AbortSignal.timeout(120000) });
    if (!response.ok) throw new Error(`${source.id}: HTTP ${response.status}`);
    bytes = Buffer.from(await response.arrayBuffer());
    if (digest(bytes) !== source.sha256) throw new Error(`${source.id}: downloaded source hash changed`);
    fs.writeFileSync(file, bytes);
  }
  return bytes;
}

// Read named members from the central directory. No archive path is used as a
// filesystem destination; callers choose each flat output filename explicitly.
function members(zip) {
  let end = zip.length - 22;
  while (end >= Math.max(0, zip.length - 65557) && zip.readUInt32LE(end) !== 0x06054b50) end--;
  if (end < Math.max(0, zip.length - 65557) || zip.readUInt32LE(end) !== 0x06054b50) throw new Error('Invalid ZIP directory');
  const entries = new Map();
  let cursor = zip.readUInt32LE(end + 16);
  for (let i = 0; i < zip.readUInt16LE(end + 10); i++) {
    if (zip.readUInt32LE(cursor) !== 0x02014b50) throw new Error('Invalid ZIP entry');
    const method = zip.readUInt16LE(cursor + 10), size = zip.readUInt32LE(cursor + 20);
    const nameSize = zip.readUInt16LE(cursor + 28), extra = zip.readUInt16LE(cursor + 30), comment = zip.readUInt16LE(cursor + 32);
    const local = zip.readUInt32LE(cursor + 42);
    const name = zip.toString('utf8', cursor + 46, cursor + 46 + nameSize);
    const start = local + 30 + zip.readUInt16LE(local + 26) + zip.readUInt16LE(local + 28);
    entries.set(name, () => {
      const compressed = zip.subarray(start, start + size);
      if (method === 0) return compressed;
      if (method === 8) return zlib.inflateRawSync(compressed, { maxOutputLength: 32 * 1024 * 1024 });
      throw new Error('Unsupported ZIP compression');
    });
    cursor += 46 + nameSize + extra + comment;
  }
  return entries;
}

async function main() {
  fs.mkdirSync(CACHE, { recursive: true });
  fs.mkdirSync(OUTPUT, { recursive: true });
  const sources = [];
  for (const pack of PACKS) {
    const entries = members(await download(pack));
    const license = entries.get('License.txt')?.();
    if (!license || !/CC0/.test(license.toString('utf8'))) throw new Error(`${pack.id}: missing CC0 notice`);
    fs.writeFileSync(path.join(OUTPUT, `${pack.id}-LICENSE.txt`), license);
    for (const name of pack.models) {
      const member = pack.folder + name + '.glb';
      const bytes = entries.get(member)?.();
      if (!bytes) throw new Error(`${pack.id}: missing ${member}`);
      const file = `${pack.id}/${name}.glb`;
      fs.mkdirSync(path.dirname(path.join(OUTPUT, file)), { recursive: true });
      fs.writeFileSync(path.join(OUTPUT, file), bytes);
      const gltf = JSON.parse(bytes.subarray(20, 20 + bytes.readUInt32LE(12)).toString('utf8'));
      const dependencies = [];
      for (const image of gltf.images || []) {
        if (!image.uri || image.uri.startsWith('data:')) continue;
        if (image.uri.includes('..') || !/^Textures\/[a-zA-Z0-9_.-]+$/.test(image.uri)) throw new Error('Unexpected source texture path');
        const texture = entries.get(pack.folder + image.uri)?.();
        if (!texture) throw new Error(`${pack.id}: missing texture ${image.uri}`);
        const textureFile = `${pack.id}/${image.uri}`;
        fs.mkdirSync(path.dirname(path.join(OUTPUT, textureFile)), { recursive: true });
        fs.writeFileSync(path.join(OUTPUT, textureFile), texture);
        dependencies.push({ file: textureFile, sha256: digest(texture) });
      }
      sources.push({ id: `${pack.id}-${name}`, file, title: name, creator: pack.creator,
        page: pack.page, download: pack.url, archiveSha256: pack.sha256, member,
        license: 'CC0-1.0', licenseFile: `${pack.id}-LICENSE.txt`, sha256: digest(bytes), bytes: bytes.length, dependencies });
      // Migrate only exact generated copies from the initial flat source layout.
      const obsolete = path.join(OUTPUT, `${pack.id}-${name}.glb`);
      if (fs.existsSync(obsolete) && digest(fs.readFileSync(obsolete)) === digest(bytes)) fs.unlinkSync(obsolete);
    }
  }
  for (const source of DIRECT) {
    const bytes = await download(source);
    fs.writeFileSync(path.join(OUTPUT, source.file), bytes);
    sources.push({ ...source, license: 'CC0-1.0', bytes: bytes.length });
  }
  fs.writeFileSync(path.join(OUTPUT, 'sources.json'), JSON.stringify({
    schema: 'realm.free-item-sources.v1', verifiedDate: '2026-09-09', sources
  }, null, 2) + '\n');
  console.log(`Free item sources ready: ${sources.length} pinned CC0 models.`);
}
if (require.main === module) main().catch(error => { console.error(error); process.exitCode = 1; });
module.exports = { main, OUTPUT };
